/**
 * @file Catálogo de referencia que hasta ahora sólo existía en la base de siembra externa.
 * @business Esta pieza preserva la fuente de verdad y la evidencia histórica que soportan decisiones y cumplimiento.
 * @system define seeders para evolucionar, mapear, sembrar o consultar PostgreSQL de forma controlada.
 */
import { refA, type DominioSembrado } from './tipos.js';
import { bloquesDeFlujos } from './workflow-catalog-flujos.js';
import { FLUJO_CLIENTE_COMPLETO } from './flujo-cliente-completo.seed-data.js';
import { FLUJO_CLIENTE_PARTNER } from './flujo-cliente-partner.seed-data.js';

/**
 * Estas 340 filas NO son datos de demostración: son el CATÁLOGO con el que el backend funciona.
 *
 * Vivían sólo en la base `seed_atlas` del servidor de desarrollo: una instalación limpia arrancaba
 * sin plantillas de contrato, sin proveedores, sin flujos y sin política de retención, y ninguna
 * pantalla decía por qué estaba vacía.
 *
 * **Ni un solo identificador literal, ni como clave ni como referencia.** Las filas se exportaron
 * de una base concreta, y en cualquier otra las mismas filas existen con OTRO `_id`. Dos
 * despliegues seguidos murieron por esto el 2026-09-17:
 *
 * 1. «duplicate key value violates unique constraint ux_app_content_entries_key» — el upsert por
 *    `_id` insertaba una fila nueva que chocaba contra la clave natural de la que ya estaba.
 * 2. «violates foreign key constraint fk_data_providers_default_retention_policy_id» — la columna
 *    apuntaba al identificador que esa política tenía en la base de origen, y no existe aquí.
 *
 * Por eso cada bloque reconcilia por su clave NATURAL y **toda columna que apunte a otra fila se
 * resuelve con `refA`** por esa misma clave. Lo que no tiene clave natural con la que resolverse
 * —quién publicó un documento de consentimiento— va a NULO antes que a una clave foránea rota: el
 * documento sigue completo sin ese metadato.
 *
 * El ORDEN de los bloques importa y por eso está escrito, no ordenado alfabéticamente: retención y
 * propósitos van primero porque los proveedores y las definiciones de features apuntan ahí.
 *
 * Tres tablas que parecían faltar **no están aquí a propósito**: `messaging.notification_templates`,
 * `risk.rating_policy_versions` y `risk.rating_policy_bands` las instala una MIGRACIÓN —están
 * incluso en la base de TEST sin ninguna siembra—, así que sembrarlas duplicaría.
 *
 * Ninguna contiene datos personales: son configuración, plantillas y definiciones.
 */
